<?php
declare(strict_types=1);

const ALLOWED_ORIGIN = 'https://annaraksha.unbeatablefoods.com';

function send_cors_headers(): void {
    $origin = $_SERVER['HTTP_ORIGIN'] ?? '';
    if ($origin === ALLOWED_ORIGIN) { header('Access-Control-Allow-Origin: '.ALLOWED_ORIGIN); header('Vary: Origin'); }
    header('Access-Control-Allow-Methods: GET, POST, DELETE, OPTIONS');
    header('Access-Control-Allow-Headers: Content-Type, Accept, Authorization');
    header('Access-Control-Max-Age: 86400');
}
function api_init(): void {
    send_cors_headers();
    if (($_SERVER['REQUEST_METHOD'] ?? 'GET') === 'OPTIONS') { http_response_code(204); exit; }
    header('Content-Type: application/json; charset=utf-8');
}
function api_json($value, int $status = 200): never {
    http_response_code($status); echo json_encode($value, JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE); exit;
}
function json_error(string $message, int $status = 500): never {
    api_json(['status' => 'error', 'message' => $message], $status);
}
function api_body(): array {
    $raw = file_get_contents('php://input') ?: '';
    $data = json_decode($raw, true);
    return is_array($data) ? $data : ($_POST ?: []);
}
function db(): PDO {
    static $db;
    if ($db instanceof PDO) return $db;
    $db = new PDO('sqlite:'.dirname(__DIR__).'/data/annaraksha.db', null, null, [
        PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION, PDO::ATTR_DEFAULT_FETCH_MODE => PDO::FETCH_ASSOC
    ]);
    $db->exec("CREATE TABLE IF NOT EXISTS storage_units (id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,state TEXT NOT NULL,city TEXT NOT NULL,lat REAL NOT NULL,lng REAL NOT NULL,grain_type TEXT NOT NULL,capacity_tonnes INTEGER NOT NULL,current_stock_tonnes INTEGER NOT NULL,moisture_pct REAL NOT NULL,risk_level TEXT NOT NULL DEFAULT 'healthy',predicted_spoilage_date TEXT,last_updated TEXT DEFAULT CURRENT_TIMESTAMP)");
    $db->exec("CREATE TABLE IF NOT EXISTS alerts (id INTEGER PRIMARY KEY AUTOINCREMENT,unit_id INTEGER NOT NULL,message TEXT NOT NULL,severity TEXT NOT NULL,tonnes_at_risk INTEGER NOT NULL,rupees_at_risk REAL NOT NULL,created_at TEXT DEFAULT CURRENT_TIMESTAMP)");
    try { $db->exec("ALTER TABLE storage_units ADD COLUMN stock_arrival_date TEXT"); } catch (Throwable $e) {}
    return $db;
}
function unit_row($id) { $s=db()->prepare('SELECT * FROM storage_units WHERE id=?'); $s->execute([$id]); return $s->fetch() ?: null; }
function unit_out(array $u): array {
    $arrival = $u['stock_arrival_date'] ?: '2026-08-15';
    $days = max(1, (int)round((strtotime('2026-09-17')-strtotime($arrival))/86400));
    foreach (['id','capacity_tonnes','current_stock_tonnes'] as $k) $u[$k]=(int)$u[$k];
    foreach (['lat','lng','moisture_pct'] as $k) $u[$k]=(float)$u[$k];
    $u['stock_arrival_date']=$arrival; $u['days_in_storage']=$days; return $u;
}
