function forecast(array $p): array {
    $crop=strtolower(trim((string)($p['grain_type']??'wheat')));$rates=['wheat'=>22750,'rice'=>24500,'moong'=>78000,'chana'=>54000,'bajra'=>19500,'jowar'=>29000];$base=['wheat'=>360,'rice'=>300,'moong'=>240,'chana'=>270,'bajra'=>210,'jowar'=>240];
    $stock=(float)($p['current_stock_tonnes']??5000)?:5000;$moist=(float)($p['moisture_pct']??12.5)?:12.5;$temp=(float)($p['temp_c']??27.5)?:27.5;$safe=in_array($crop,['moong','chana'],true)?12:13;$facility=(string)($p['facility_type']??'Modern Steel Silo');
    $allow=max(12,round(($base[$crop]??280)*pow(2,($safe-$moist)/1.7)*pow(2,(22-$temp)/6.5)*(strpos($facility,'Silo')!==false?1.15:(strpos($facility,'Godown')!==false?1:.78))));
    $now=strtotime('2026-09-17');$arrival=strtotime((string)($p['stock_arrival_date']??'2026-08-01'));if(!$arrival)$arrival=$now-35*86400;$days=max(1,round(($now-$arrival)/86400));$dts=round($allow-$days);$breach=date('Y-m-d',$now+$dts*86400);
    if($dts<=0){$window='ACTIVE_BREACH';$badge='🚨 ACTIVE SPOILAGE';$color='#ef4444';$severity='CRITICAL';}elseif($dts<=30){$window='BREACH_WITHIN_30D';$badge='🚨 URGENT (<30d)';$color='#f43f5e';$severity='CRITICAL';}elseif($dts<=60){$window='BREACH_WITHIN_60D';$badge='⚠️ 2-MONTH HAZARD (<60d)';$color='#f59e0b';$severity='HIGH';}else{$window='SAFE_BUFFER';$badge='🛡️ SAFE (>90d)';$color='#10b981';$severity='LOW';}
    $timeline=[];foreach([0,15,30,45,60] as $o){$age=$days+$o;$ratio=$age/$allow;$spoiled=($o>=$dts||$dts<=0)?min($stock,round($stock*(.12+.88*pow(max(0,$o-max(0,$dts))/45,1.25)))):0;$loss=$spoiled*($rates[$crop]??23000);$timeline[]=['day_offset'=>$o,'date'=>date('Y-m-d',$now+$o*86400),'label'=>$o?'Day +'.$o:'Today (Day 0)','storage_age_days'=>$age,'dml_pct'=>min(4.5,round(.5*pow($ratio,2.1),2)),'spoilage_risk_pct'=>min(100,max(1,round(100/(1+exp(-7.5*($ratio-.95)))))),'spoiled_tonnes'=>$spoiled,'loss_rupees'=>$loss,'loss_lakhs'=>round($loss/100000,1),'loss_cr'=>round($loss/10000000,2),'biological_state'=>$o<$dts-15?'Stable intergranular ERH; microbial respiration dormant.':'Thermal respiration rising; early fungal hyphae expansion.'];}
    $day60=$timeline[4];$cut=date('Y-m-d',$now+max(3,$dts-8)*86400);
    return ['unit_id'=>$p['unit_id']??null,'facility_name'=>$p['name']??'Regional Silo Facility','location'=>$p['location']??'India','grain_type'=>$crop,'current_stock_tonnes'=>$stock,'moisture_pct'=>$moist,'temp_c'=>$temp,'facility_type'=>$facility,'stock_arrival_date'=>date('Y-m-d',$arrival),'days_in_storage'=>$days,'total_safe_storage_days'=>$allow,'days_to_spoilage_breach'=>$dts,'breach_date'=>$breach,'window_status'=>$window,'status_badge'=>$badge,'status_color'=>$color,'severity'=>$severity,'urgency_headline'=>"Spoilage threshold breach projected in $dts days ($breach).",'wastage_at_60_days_tonnes'=>$day60['spoiled_tonnes'],'wastage_at_60_days_pct'=>round($day60['spoiled_tonnes']/$stock*100),'rupees_loss_at_60_days_cr'=>$day60['loss_cr'],'timeline'=>$timeline,'salvage_plan'=>['salvage_feasible'=>$dts>5||$days<$allow,'salvage_deadline_date'=>$cut,'days_to_execute_salvage'=>max(1,$dts-8),'primary_preservation_action'=>$moist>13.5?'Emergency Nocturnal Aeration (5.5 hrs/night @ <65% ambient RH)':'Preventive Turning & Inter-Chamber Recirculation','target_moisture_extraction'=>max(.5,round($moist-$safe,1)).'% reduction needed','liquidation_recommendation'=>$dts<=60?'Allocate '.number_format($stock).' T to regional dal/flour millers before '.$cut.' to recover inventory.':'Stock stable for strategic national buffer reserve. No urgent market offloading required.']];
}
